// ParsePorts 解析端口规格，支持预设（common/web/full）与 "80,443,8000-8100" 自定义格式。
func ParsePorts(spec string) ([]int, error) {
	spec = strings.TrimSpace(strings.ToLower(spec))
	if spec == "" {
		spec = "common"
	}
	var tokens []string
	switch spec {
	case "common":
		tokens = strings.Fields(presetCommon)
	case "web":
		tokens = strings.Fields(presetWeb)
	case "full":
		tokens = []string{"1-65535"}
	default:
		tokens = strings.FieldsFunc(spec, func(r rune) bool {
			return r == ',' || r == ' ' || r == '\n' || r == '\t' || r == ';'
		})
	}
	seen := map[int]struct{}{}
	var ports []int
	for _, tk := range tokens {
		tk = strings.TrimSpace(tk)
		if tk == "" {
			continue
		}
		if lo, hi, ok := strings.Cut(tk, "-"); ok {
			l, err1 := strconv.Atoi(strings.TrimSpace(lo))
			h, err2 := strconv.Atoi(strings.TrimSpace(hi))
			if err1 != nil || err2 != nil || l < 1 || h > 65535 || l > h {
				return nil, fmt.Errorf("无效端口范围: %q", tk)
			}
			for p := l; p <= h; p++ {
				if _, dup := seen[p]; !dup {
					seen[p] = struct{}{}
					ports = append(ports, p)
				}
			}
		} else {
			p, err := strconv.Atoi(tk)
			if err != nil || p < 1 || p > 65535 {
				return nil, fmt.Errorf("无效端口: %q", tk)
			}
			if _, dup := seen[p]; !dup {
				seen[p] = struct{}{}
				ports = append(ports, p)
			}
		}
	}
	sort.Ints(ports)
	if len(ports) == 0 {
		return nil, fmt.Errorf("端口列表为空")
	}
	return ports, nil
}
